import{_ as t,a,c as o,ac as n}from"./chunks/framework.BSuaGltH.js";const p=JSON.parse('{"title":"第一册：英语初阶 · Lesson 74 What did they do?","description":"学习 不规则过去式，配有原创例句、重点词汇和带解析的自测。","frontmatter":{"title":"第一册：英语初阶 · Lesson 74 What did they do?","description":"学习 不规则过去式，配有原创例句、重点词汇和带解析的自测。","showdocs":{"topics":[{"id":"english","title":"英语","link":"/topics/english/"}],"kind":"路线与能力起点","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"新概念英语经典版第1册课时","summary":"学习 不规则过去式，配有原创例句、重点词汇和带解析的自测。","status":"active","related":[{"title":"程序员英语 08：一次完整的阅读与协作实战","link":"/life/english/programmer/practice","kind":"读写与对话练习","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语","link":"/life/english/new-concept/book-2/unit-01/vocabulary","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 第17–24课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-02","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 字母索引与第1–16课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-01","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 复习与自测","link":"/life/english/new-concept/book-2/unit-01/review","kind":"读写与对话练习","scope":"general","audience":"general"}],"prev":{"text":"第一册：英语初阶 · Lesson 73 The way to King Street","link":"/life/english/new-concept/book-1/unit-04/lesson-073"},"next":{"text":"第一册：英语初阶 · Lesson 75 Uncomfortable shoes","link":"/life/english/new-concept/book-1/unit-04/lesson-075"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"第一册：英语初阶 · Lesson 73 The way to King Street","link":"/life/english/new-concept/book-1/unit-04/lesson-073"},"next":{"text":"第一册：英语初阶 · Lesson 75 Uncomfortable shoes","link":"/life/english/new-concept/book-1/unit-04/lesson-075"}},"headers":[],"relativePath":"life/english/new-concept/book-1/unit-04/lesson-074.md","filePath":"life/english/new-concept/book-1/unit-04/lesson-074.md"}'),i={name:"life/english/new-concept/book-1/unit-04/lesson-074.md"};function s(l,e,r,d,h,c){return a(),o("div",null,[...e[0]||(e[0]=[n('<h1 id="第一册-英语初阶-·-lesson-74-what-did-they-do" tabindex="-1">第一册：英语初阶 · Lesson 74 What did they do? <a class="header-anchor" href="#第一册-英语初阶-·-lesson-74-what-did-they-do" aria-label="Permalink to &quot;第一册：英语初阶 · Lesson 74 What did they do?&quot;">​</a></h1><p><a href="/life/english/new-concept/overview">系列目录</a> · <a href="/life/english/new-concept/book-1/contents">本册目录</a> · <a href="/life/english/new-concept/book-1/unit-04/overview">单元 4</a> · <a href="/life/english/new-concept/book-1/unit-04/lesson-073">配套课 Lesson 73</a></p><h2 id="学习目标与内容导读" tabindex="-1">学习目标与内容导读 <a class="header-anchor" href="#学习目标与内容导读" aria-label="Permalink to &quot;学习目标与内容导读&quot;">​</a></h2><p>叙述问路和找到目的地的过程 本课要掌握不规则过去式，能够理解人物、对象及说话目的，并把相同结构用于自己的生活。本课将前一课的结构迁移到另一个例子；请先口头作答，再写出完整句子，不只替换单个单词。</p><p>本课为配套句型训练；先回顾相邻奇数课，再独立完成本页的原创练习。</p><h2 id="单词与搭配" tabindex="-1">单词与搭配 <a class="header-anchor" href="#单词与搭配" aria-label="Permalink to &quot;单词与搭配&quot;">​</a></h2><table tabindex="0"><thead><tr><th>单词</th><th>音标</th><th>词性</th><th>本页义项</th><th>搭配</th></tr></thead><tbody><tr><td>way</td><td>/weɪ/</td><td>n.</td><td>路线；方法</td><td>the way to the station</td></tr><tr><td>lose</td><td>/luːz/</td><td>v.</td><td>失去；迷失</td><td>lose the way</td></tr><tr><td>suddenly</td><td>/ˈsʌdənli/</td><td>adv.</td><td>突然</td><td>stop suddenly</td></tr><tr><td>understand</td><td>/ˌʌndəˈstænd/</td><td>v.</td><td>理解</td><td>understand a question</td></tr></tbody></table><h2 id="短语与句型" tabindex="-1">短语与句型 <a class="header-anchor" href="#短语与句型" aria-label="Permalink to &quot;短语与句型&quot;">​</a></h2><ul><li>lose the way — 迷路</li><li>the way to — 到某处的路</li></ul><h2 id="语法讲解-不规则过去式" tabindex="-1">语法讲解：不规则过去式 <a class="header-anchor" href="#语法讲解-不规则过去式" aria-label="Permalink to &quot;语法讲解：不规则过去式&quot;">​</a></h2><p>部分高频动词的过去式不是加 ed：go→went、see→saw、say→said、take→took。肯定句使用过去式，问句和否定句中 did 后恢复原形。复述路线可以按先后顺序组织动作，但 next、then 等顺序词不自动决定时态；应先确认整个故事发生在过去。人名变化不会改变过去式形式。</p><h2 id="原创例句与结构分析" tabindex="-1">原创例句与结构分析 <a class="header-anchor" href="#原创例句与结构分析" aria-label="Permalink to &quot;原创例句与结构分析&quot;">​</a></h2><blockquote><p>Did the guard show you the right road?</p></blockquote><p>警卫给你指了正确的路吗？</p><p>Did 前置询问过去事件，show 恢复原形；you 是接受者，the right road 是被指出的信息。</p><h2 id="易错辨析" tabindex="-1">易错辨析 <a class="header-anchor" href="#易错辨析" aria-label="Permalink to &quot;易错辨析&quot;">​</a></h2><p>did 后用 show 而非 showed；went 只放在没有 did 的过去肯定句中。</p><h2 id="听说训练" tabindex="-1">听说训练 <a class="header-anchor" href="#听说训练" aria-label="Permalink to &quot;听说训练&quot;">​</a></h2><p>请同伴朗读本课原创示范，或先自行录音，再遮住文字听写“Did the guard show you the right road?”。核对词序与漏词后，用下方句子分析说明每个词组的作用。随后不看原句说出中文意思，再换一个对象重新说一句。没有录音时，可用同伴朗读和问答完成同样的训练。</p><h2 id="读写训练" tabindex="-1">读写训练 <a class="header-anchor" href="#读写训练" aria-label="Permalink to &quot;读写训练&quot;">​</a></h2><h3 id="阅读材料-本站原创" tabindex="-1">阅读材料（本站原创） <a class="header-anchor" href="#阅读材料-本站原创" aria-label="Permalink to &quot;阅读材料（本站原创）&quot;">​</a></h3><p>Did the guard show you the right road? We took the wrong bus and went to the harbour.</p><h3 id="表达任务" tabindex="-1">表达任务 <a class="header-anchor" href="#表达任务" aria-label="Permalink to &quot;表达任务&quot;">​</a></h3><p>围绕“叙述问路和找到目的地的过程”写两至三句，再读给同伴听。至少使用一次不规则过去式，改变一个人物或对象后再说一遍。</p><details class="details custom-block"><summary>写作提示与点评</summary><p>Did 前置询问过去事件，show 恢复原形；you 是接受者，the right road 是被指出的信息。 Took 与 went 是并列的过去时谓语，分别来自 take 和 go；and 连接两个先后相关的动作。</p></details><h2 id="课后自测" tabindex="-1">课后自测 <a class="header-anchor" href="#课后自测" aria-label="Permalink to &quot;课后自测&quot;">​</a></h2><h3 id="练习-1" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1" aria-label="Permalink to &quot;练习 1&quot;">​</a></h3><p>填原形：Did the guard ___ (show) you the road?</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> show</p><p><strong>解析：</strong> 按本课规则判断：部分高频动词的过去式不是加 ed：go→went、see→saw、say→said、take→took。肯定句使用过去式，问句和否定句中 did 后恢复原形。复述路线可以按先后顺序组织动作，但 next、then 等顺序词不自动决定时态；应先确认整个故事发生在过去。人名变化不会改变过去式形式。</p></details><h3 id="练习-2" tabindex="-1">练习 2 <a class="header-anchor" href="#练习-2" aria-label="Permalink to &quot;练习 2&quot;">​</a></h3><p>把“警卫给你指了正确的路吗？”译成英语，保留人物、动作与时间信息。</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> Did the guard show you the right road?</p><p><strong>解析：</strong> Did 前置询问过去事件，show 恢复原形；you 是接受者，the right road 是被指出的信息。</p></details><h3 id="练习-3" tabindex="-1">练习 3 <a class="header-anchor" href="#练习-3" aria-label="Permalink to &quot;练习 3&quot;">​</a></h3><p>说明下面句子表达的信息，并译成中文：We took the wrong bus and went to the harbour.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> 我们坐错了公交车，去了港口。</p><p><strong>解析：</strong> Took 与 went 是并列的过去时谓语，分别来自 take 和 go；and 连接两个先后相关的动作。</p></details><h2 id="复习导航" tabindex="-1">复习导航 <a class="header-anchor" href="#复习导航" aria-label="Permalink to &quot;复习导航&quot;">​</a></h2><p>本课重点：不规则过去式。复习时先遮住答案重做自测，再将示范中的人物、时间或条件改为自己的情境；解释改动后哪些词需要变化。</p><p><a href="/life/english/new-concept/book-1/unit-04/grammar">单元语法</a> · <a href="/life/english/new-concept/book-1/unit-04/vocabulary">单元单词</a> · <a href="/life/english/new-concept/book-1/unit-04/review">单元自测</a></p><p><a href="/life/english/new-concept/book-1/unit-04/lesson-073">上一课</a> · <a href="/life/english/new-concept/book-1/unit-04/overview">单元目录</a> · <a href="/life/english/new-concept/book-1/unit-04/lesson-075">下一课</a></p><hr><p>本站原创学习伴读：保留经典版课号和课名，讲解、例句与练习独立编写。重点词汇用于本页学习，不等同于教材全部生词表；教材课文、完整译文、原题与录音请配合自己的正版教材使用。</p>',41)])])}const b=t(i,[["render",s]]);export{p as __pageData,b as default};
